46-  // only past epochs are claimable, hence shift by one here
47-  const length = veaEpochOutboxClaimableNow - veaEpochOutboxWatchLowerBound;
48-  const veaEpochOutboxCheckClaimsRangeArray: number[] = Array.from(
49-    { length },
